//! The generated-file rule that lint and the change review share. A source file is
//! generated when its first line is a `#` comment that starts with "generated by", in
//! any letter case: `# generated by tool` and `# GENERATED by tool` both qualify, and a
//! hand-written `# Generated helpers` line does not. Lint leaves such a file alone, and
//! the review lists it instead of diffing it.
const std = @import("std");

/// Whether `bytes` opens with the generated marker: its first line is a `#` comment
/// whose text starts with "generated by", in any letter case.
pub fn isGenerated(bytes: []const u8) bool {
    const end = std.mem.indexOfScalar(u8, bytes, '\n') orelse bytes.len;
    var line = std.mem.trim(u8, bytes[0..end], " \t\r");
    if (line.len == 0 or line[0] != '#') return false;
    line = std.mem.trimStart(u8, line[1..], " \t");
    const marker = "generated by";
    if (line.len < marker.len or !std.ascii.eqlIgnoreCase(line[0..marker.len], marker)) return false;
    return line.len == marker.len or !std.ascii.isAlphanumeric(line[marker.len]);
}

test "generated marker accepts both letter cases of generated by" {
    try std.testing.expect(isGenerated("# generated by tools/gen_ports.py\nmodule x\n"));
    try std.testing.expect(isGenerated("# GENERATED by gen_ports.py\npublic func f() -> int:\n    return 1\n"));
    try std.testing.expect(isGenerated("  # Generated by hand-run script\n"));
}

test "generated marker refuses other first lines and comments that only mention generated" {
    try std.testing.expect(!isGenerated("module x\n# generated by tool\n"));
    try std.testing.expect(!isGenerated("# not generated here\n"));
    try std.testing.expect(!isGenerated("# Generated helpers for the parser\n"));
    try std.testing.expect(!isGenerated("# Generated: do not edit\n"));
    try std.testing.expect(!isGenerated("# generated byte tables\n"));
    try std.testing.expect(!isGenerated("generated by tool\n"));
    try std.testing.expect(!isGenerated(""));
}
